    def write_to_file(self, filepath: str):
        # The Blacklist: These keys trigger alternative solver architectures
        # and will crash standard runs if populated with the template's dummy data.
        toxic_keys = {
            'CONFIG_LIST',
            'MULTIPOINT_MACH_NUMBER', 'MULTIPOINT_WEIGHT', 'MULTIPOINT_AOA',
            'MULTIPOINT_SIDESLIP_ANGLE', 'MULTIPOINT_TARGET_CL',
            'MULTIPOINT_REYNOLDS_NUMBER', 'MULTIPOINT_FREESTREAM_TEMPERATURE',
            'MULTIPOINT_FREESTREAM_PRESSURE', 'MULTIPOINT_OUTLET_VALUE',
            'MULTIPOINT_MESH_FILENAME'
        }

        with open(filepath, 'w') as f:
            for key, value in self.__dict__.items():
                # Block the toxic keys and any obviously empty placeholders
                if key in toxic_keys or value == '' or value == '()':
                    continue

                # Format the values SU2 expects
                if isinstance(value, bool):
                    str_val = 'YES' if value else 'NO'
                elif isinstance(value, tuple):
                    str_val = '( ' + ', '.join(str(x) for x in value) + ' )'
                elif isinstance(value, list):
                    str_val = ' '.join(str(x) for x in value)
                else:
                    str_val = str(value)

                f.write(f"{key}= {str_val}\n")
